"""Sequential batch runner preserving Meridian CRM 4.2 error semantics."""


def run_jobs(jobs: list[dict], executor) -> list[dict]:
    """Execute jobs sequentially and return one log entry per attempted job."""
    run_log: list[dict] = []

    for job in jobs:
        policy = job["on_error"]["policy"]
        max_attempts = (
            job["on_error"]["retries"] + 1 if policy == "RETRY" else 1
        )
        attempts = 0

        for _ in range(max_attempts):
            attempts += 1
            try:
                executor(job)
            except Exception:
                if policy == "RETRY" and attempts < max_attempts:
                    continue

                if policy == "CONTINUE":
                    run_log.append(
                        {
                            "name": job["name"],
                            "attempts": attempts,
                            "outcome": "skip",
                            "audits": ["BATCH_ROWSKIP"],
                        }
                    )
                    break

                run_log.append(
                    {
                        "name": job["name"],
                        "attempts": attempts,
                        "outcome": "abort",
                        "audits": [],
                    }
                )
                return run_log
            else:
                run_log.append(
                    {
                        "name": job["name"],
                        "attempts": attempts,
                        "outcome": "ok",
                        "audits": [],
                    }
                )
                break

    return run_log
